module gold_leaf_fold (\n    input clk,\n    input rst_n,\n    input start,\n    input [3:0] n, m,\n    input [63:0] grid,  // row-major [7:0][7:0]\n    output reg [3:0] r1, c1, r2, c2,\n    output reg done\n);\n\n    // State definitions\n    localparam bit [2:0] IDLE           = 3'd0;\n    localparam bit [2:0] CHECK_FOLD     = 3'd1;\n    localparam bit [2:0] NEXT_FOLD      = 3'd2;\n    localparam bit [2:0] DONE_STATE     = 3'd3;\n    localparam bit [2:0] CHECK_VALID    = 3'd4;\n    \n    reg [2:0] state, next_state;\n    reg [2:0] fold_type;  // 0:H, 1:V, 2:D1, 3:D2\n    reg [3:0] fold_param;\n    \n    // Fold validity checking\n    reg checking;\n    reg valid_found;\n    reg [3:0] check_r, check_c;\n    reg [3:0] mr, mc;  // Mirror coordinates\n    reg conflict;\n    reg [7:0] cycle_count;\n    localparam [7:0] MAX_CYCLES = 8'd100;\n    \n    // Grid access helper\n    function get_cell;\n        input [3:0] r, c;\n        begin\n            get_cell = grid[r * 8 + c];\n        end\n    endfunction\n    \n    // Main state machine\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            fold_type <= 3'd0;\n            fold_param <= 4'd0;\n            done <= 1'b0;\n            r1 <= 4'd0; c1 <= 4'd0; r2 <= 4'd0; c2 <= 4'd0;\n            valid_found <= 1'b0;\n            cycle_count <= 8'd0;\n            checking <= 1'b0;\n            check_r <= 4'd0;  check_c <= 4'd0;\n            mr <= 4'd0;  mc <= 4'd0;\n            conflict <= 1'b0;\n        end else begin\n            cycle_count <= cycle_count + 8'd1;\n            \n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    valid_found <= 1'b0;\n                    cycle_count <= 8'd0;\n                    if (start) begin\n                        state <= CHECK_VALID;\n                        fold_type <= 3'd0;\n                        fold_param <= 4'd1;  // Start H at i=1\n                        checking <= 1'b1;\n                        conflict <= 1'b0;\n                        check_r <= 4'd0;\n                        check_c <= 4'd0;\n                    end\n                end\n                \n                CHECK_VALID: begin\n                    // Iterate through grid cells\n                    if (!conflict && check_r < n && check_c < m) begin\n                        case (fold_type)\n                            3'd0: begin  // H\n                                if (check_r < fold_param) begin\n                                    mr = {1'b0, (2 * fold_param) + 1'b1 - check_r};\n                                    mc = check_c;\n                                    if (mr < n) begin\n                                        if (get_cell(check_r, check_c) && get_cell(mr, mc))\n                                            conflict <= 1'b1;\n                                    end\n                                end\n                            end\n                            3'd1: begin  // V\n                                if (check_c < fold_param) begin\n                                    mr = check_r;\n                                    mc = {1'b0, (2 * fold_param) + 1'b1 - check_c};\n                                    if (mc < m) begin\n                                        if (get_cell(check_r, check_c) && get_cell(mr, mc))\n                                            conflict <= 1'b1;\n                                    end\n                                end\n                            end\n                            // Diagonals omitted for brevity\n                        endcase\n                        \n                        // Next cell\n                        if (check_c < m - 1) check_c <= check_c + 1;\n                        else begin\n                            check_c <= 4'd0;\n                            if (check_r < 4'd7) check_r <= check_r + 1;\n                        end\n                    end else begin\n                        // Validation complete\n                        valid_found <= !conflict;\n                        state <= CHECK_FOLD;\n                    end\n                end\n                \n                CHECK_FOLD: begin\n                    if (valid_found) begin\n                        case (fold_type)\n                            3'd0: {r1, c1, r2, c2} <= {fold_param, 4'd1, fold_param, m};\n                            3'd1: {r1, c1, r2, c2} <= {4'd1, fold_param, n, fold_param};\n                            // Diagonals omitted\n                        endcase\n                        state <= DONE_STATE;\n                    end else begin\n                        state <= NEXT_FOLD;\n                    end\n                end\n                \n                NEXT_FOLD: begin\n                    case (fold_type)\n                        3'd0: begin  // Horizontal\n                            if (fold_param < n - 1) fold_param <= fold_param + 1;\n                            else {fold_type, fold_param} <= {3'd1, 4'd1};\n                        end\n                        3'd1: begin  // Vertical\n                            if (fold_param < m - 1) fold_param <= fold_param + 1;\n                            else fold_type <= 3'd2;\n                        end\n                        // Diagonals\n                        default: fold_type <= fold_type + 1;\n                    endcase\n                    \n                    if (fold_type == 3'd3) begin\n                        state <= DONE_STATE;\n                    end else begin\n                        checking <= 1'b1;\n                        conflict <= 1'b0;\n                        check_r <= 4'd0;\n                        check_c <= 4'd0;\n                        state <= CHECK_VALID;\n                    end\n                end\n                \n                DONE_STATE: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n            \n            // Timeout protection\n            if (cycle_count >= MAX_CYCLES && state != IDLE) \n                state <= DONE_STATE;\n        end\n    end\nendmodule